/** Scratch verification of the built impact-visibility study (2026-10-31). Run from the worktree root:
 *   node --import tsx <this> --study=impact-visibility-2026-11 --port=8791 --out=FILE.json
 * 1. manifest ↔ key consistency; 2. labels API validation on a throwaway copy (never the
 * worktree's labels/); 3. every clip probed with ffprobe; 4. page loads in headless Chromium
 * against `npm run serve` on --port, no console/page errors, every clip decodes;
 * 5. clip timing: the clip frame at 1.0 s equals the ride render frame at frame/40 s. */
import {readFileSync, writeFileSync, mkdirSync, copyFileSync, existsSync, readdirSync, rmSync} from 'node:fs';
import {execFileSync, spawn} from 'node:child_process';
import {createServer} from 'node:http';
import {join} from 'node:path';
import {gunzipSync} from 'node:zlib';
import assert from 'node:assert/strict';

const arg = (k: string) => process.argv.find(a => a.startsWith(`--${k}=`))?.slice(k.length + 3);
const study = arg('study')!, port = Number(arg('port')), ROOT = process.cwd(), SCR = '/tmp/claude-1000/-home-wyss-line/897a8423-a8a8-40b1-ab25-a90f46eae018/scratchpad';
const dir = `generated/label-studies/${study}`, manifest = JSON.parse(readFileSync(join(dir, 'manifest.json'), 'utf8'));
const key = JSON.parse(readFileSync(`labels/studies/${study}.key.json`, 'utf8'));
const report: any = {study};

// 1. manifest ↔ key
assert.equal(manifest.clips.length, key.length);
for (const [i, p] of key.entries()) {
  const c = manifest.clips[i];
  assert.equal(c.id, `pair${p.pair}`);
  for (const s of ['left', 'right']) assert.equal(c[s].src, `/${dir}/clips/pair${p.pair}-${s}.mp4`);
}
assert.deepEqual(manifest.questions, [{id: 'bigger', options: ['left', 'right', 'same', 'neither']}]);
assert.equal(manifest.hitAt, 1); assert.equal(manifest.length, 1.8);
report.manifestMatchesKey = true;

// 2. labels API on a throwaway root
const tmp = join(SCR, 'api-root');
rmSync(tmp, {recursive: true, force: true}); mkdirSync(join(tmp, dir), {recursive: true});
copyFileSync(join(dir, 'manifest.json'), join(tmp, dir, 'manifest.json'));
const {createLabelsApi} = await import(join(ROOT, 'scripts/gallery/labels_api.ts'));
const handle = createLabelsApi(tmp);
const server = createServer((req, res) => {handle(req, res, new URL(req.url!, 'http://x')).then((ok: boolean) => {if (!ok) {res.writeHead(404); res.end();}});});
await new Promise<void>(r => server.listen(port + 1, '127.0.0.1', () => r()));
const api = `http://127.0.0.1:${port + 1}/api/labels/${study}`;
const post = (body: any) => fetch(api, {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body)}).then(r => r.status);
const statuses: Record<string, number[]> = {valid: [], wrongAnswer: [], unknownClip: [], missing: []};
for (const c of manifest.clips) for (const v of ['left', 'right', 'same', 'neither'])
  statuses.valid.push(await post({clip: c.id, skipped: false, answers: {bigger: v}, note: '', viewMs: 1, at: 'test'}));
statuses.wrongAnswer.push(await post({clip: 'pair1', skipped: false, answers: {bigger: 'maybe'}}));
statuses.unknownClip.push(await post({clip: 'pair999', skipped: false, answers: {bigger: 'left'}}));
statuses.missing.push(await post({clip: 'pair1', skipped: false, answers: {}}));
const got = await (await fetch(api)).json();
server.close();
report.labelsApi = {validPosts: statuses.valid.length, allValidOk: statuses.valid.every(s => s === 200), wrongAnswer: statuses.wrongAnswer[0],
  unknownClip: statuses.unknownClip[0], missingAnswer: statuses.missing[0], labeledAfter: got.labeled.length,
  rowsWritten: readFileSync(join(tmp, 'labels/studies', study + '.jsonl'), 'utf8').trim().split('\n').length};
assert.ok(report.labelsApi.allValidOk && report.labelsApi.labeledAfter === manifest.clips.length);
assert.ok(!existsSync(`labels/studies/${study}.jsonl`), 'the worktree must hold no answers');

// 3. clips
const probe = (f: string) => JSON.parse(execFileSync('ffprobe', ['-v', 'error', '-show_entries', 'stream=codec_type,codec_name,width,height,r_frame_rate:format=duration', '-of', 'json', f]).toString());
const clips: any[] = [];
for (const c of manifest.clips) for (const s of ['left', 'right']) {
  const f = c[s].src.slice(1), p = probe(f), v = p.streams.find((x: any) => x.codec_type === 'video'), a = p.streams.find((x: any) => x.codec_type === 'audio');
  clips.push({f, duration: +p.format.duration, w: v.width, h: v.height, codec: v.codec_name, fps: v.r_frame_rate, audio: !!a});
}
report.clips = {count: clips.length, allExist: clips.length === 2 * key.length, durations: [Math.min(...clips.map(c => c.duration)), Math.max(...clips.map(c => c.duration))],
  sizes: [...new Set(clips.map(c => `${c.w}x${c.h}`))], codecs: [...new Set(clips.map(c => c.codec))], fps: [...new Set(clips.map(c => c.fps))], allAudio: clips.every(c => c.audio)};

// 5. timing: ride render duration vs track; clip frame at 1.0 s vs ride frame at frame/40
const gray = (file: string, t: number) => execFileSync('ffmpeg', ['-v', 'error', '-ss', t.toFixed(4), '-i', file, '-frames:v', '1', '-vf', 'scale=320:180,format=gray', '-f', 'rawvideo', '-'], {maxBuffer: 1 << 24});
const mad = (a: Buffer, b: Buffer) => {let s = 0; for (let i = 0; i < a.length; i++) s += Math.abs(a[i] - b[i]); return s / a.length;};
const timing: any[] = [];
const sample = key.filter((p: any) => p.group === 'anchor' || p.block === 'R').slice(0, 10);
for (const p of sample) for (const s of ['left', 'right']) {
  const h = p[s], ride = join(dir, 'rides', `heldout~${h.song}~${h.seed}.mp4`), clip = join(dir, 'clips', `pair${p.pair}-${s}.mp4`);
  const rideDur = +probe(ride).format.duration, track = JSON.parse(gunzipSync(readFileSync(h.source)).toString());
  const ref = gray(clip, 1.0), offsets: Record<string, number> = {};
  for (const df of [-2, -1, 0, 1, 2]) offsets[df] = +mad(ref, gray(ride, (h.frame + df) / 40)).toFixed(2);
  const best = Object.entries(offsets).sort((a, b) => a[1] - b[1])[0][0];
  timing.push({pair: p.pair, side: s, frame: h.frame, rideSeconds: rideDur, trackFrames: track.duration, madByPhysicsFrameOffset: offsets, bestOffset: Number(best)});
}
report.timing = timing;
report.timingAllBestAtZero = timing.every(t => t.bestOffset === 0);

// 4. page in headless Chromium
const serve = spawn(process.execPath, ['--import', 'tsx', 'scripts/serve.ts'], {env: {...process.env, PORT: String(port)}, stdio: ['ignore', 'pipe', 'pipe']});
await new Promise<void>((done, fail) => {serve.stdout.on('data', d => String(d).includes('review server') && done()); serve.once('exit', () => fail(new Error('serve exited')));});
const {chromium} = await import(join(ROOT, 'node_modules/playwright/index.mjs'));
const browser = await chromium.launch();
try {
  const page = await browser.newPage({viewport: {width: 1440, height: 900}});
  const errors: string[] = [], failed: string[] = [], posts: string[] = [];
  page.on('console', m => {if (m.type() === 'error' || m.type() === 'warning') errors.push(`${m.type()}: ${m.text()}`);});
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('requestfailed', r => failed.push(r.url()));
  page.on('request', r => {if (r.method() !== 'GET') posts.push(r.url());});
  await page.goto(`http://127.0.0.1:${port}/motion-gallery/pairs.html?study=${study}`);
  await page.waitForFunction(() => (document.getElementById('progress')?.textContent ?? '').includes('Pair'), null, {timeout: 20000});
  await page.waitForFunction(() => ['left', 'right'].every(id => (document.getElementById(id) as HTMLVideoElement).readyState >= 2), null, {timeout: 20000});
  await page.waitForTimeout(2500);
  const ui = await page.evaluate(() => ({progress: document.getElementById('progress')!.textContent, prompt: document.getElementById('prompt')!.textContent,
    choices: [...document.querySelectorAll('#choices button')].map(b => b.textContent), status: document.getElementById('status')!.textContent,
    t: ['left', 'right'].map(id => (document.getElementById(id) as HTMLVideoElement).currentTime),
    ledSeen: !!document.querySelector('.led')}));
  await page.screenshot({path: join(SCR, 'page.png')});
  // every clip decodes in this browser
  const decode = await page.evaluate(async (srcs: string[]) => {
    const bad: string[] = [];
    for (const src of srcs) {
      const v = document.createElement('video'); v.muted = true; v.preload = 'auto'; v.src = src;
      const ok = await new Promise<boolean>(r => {v.onloadeddata = () => r(true); v.onerror = () => r(false); setTimeout(() => r(false), 10000);});
      if (!ok || Math.abs(v.duration - 1.8) > .06) bad.push(`${src} ${v.duration}`);
      v.removeAttribute('src'); v.load();
    }
    return bad;
  }, manifest.clips.flatMap((c: any) => [c.left.src, c.right.src]));
  report.page = {ui, consoleErrorsOrWarnings: errors, failedRequests: failed, nonGetRequests: posts, clipsNotDecoding: decode};
} finally {await browser.close(); serve.kill();}
assert.ok(!existsSync(`labels/studies/${study}.jsonl`), 'the page check must not write answers');
writeFileSync(arg('out')!, JSON.stringify(report, null, 1));
console.log(JSON.stringify(report, null, 1));
process.exit(0);

